def minimum_increasing_subsequence_removals(nums):
    import bisect
    tails=[]
    for number in nums:
        value=-number;position=bisect.bisect_right(tails,value)
        if position==len(tails):tails.append(value)
        else:tails[position]=value
    return len(tails)

